public(package) fun request_add_stake(
  pool: &mut StakingPool,
  stake: Balance<SUI>,
  stake_activation_epoch: u64,
  ctx: &mut TxContext,
 ): StakedSui {
  let sui_amount = stake.value();
  assert!(!pool.is_inactive(), EDelegationToInactivePool);
  assert!(sui_amount > 0, EDelegationOfZeroSui);
  pool.pending_stake = pool.pending_stake + sui_amount;
  StakedSui {
  id: object::new(ctx),
  pool_id: object::id(pool),
  stake_activation_epoch,
  principal: stake,
  }
 }

public(package) fun deposit_rewards(pool: &mut StakingPool, rewards: Balance<SUI>) {
  pool.sui_balance = pool.sui_balance + rewards.value();
  pool.rewards_pool.join(rewards);
 }

public(package) fun activate_staking_pool(pool: &mut StakingPool, activation_epoch: u64) {
  pool.exchange_rates.add(activation_epoch, initial_exchange_rate());
  assert!(pool.is_preactive(), EPoolAlreadyActive);
  assert!(!pool.is_inactive(), EActivationOfInactivePool);
  pool.activation_epoch.fill(activation_epoch);
 }

fun initial_exchange_rate(): PoolTokenExchangeRate {
  PoolTokenExchangeRate { sui_amount: 0, pool_token_amount: 0 }
 }

public(package) fun request_set_commission_rate(self: &mut Validator, new_commission_rate: u64) {
  assert!(new_commission_rate <= MAX_COMMISSION_RATE, ECommissionRateTooHigh);
  self.next_epoch_commission_rate = new_commission_rate;
 }

public(package) fun set_candidate_commission_rate(self: &mut Validator, new_commission_rate: u64) {
  assert!(self.is_preactive(), ENotValidatorCandidate);
  assert!(new_commission_rate <= MAX_COMMISSION_RATE, ECommissionRateTooHigh);
  self.commission_rate = new_commission_rate;
 }

public(package) fun deposit_stake_rewards(self: &mut Validator, reward: Balance<SUI>) {
  self.next_epoch_stake = self.next_epoch_stake + reward.value();
  self.staking_pool.deposit_rewards(reward);
 }

public(package) fun update_name(self: &mut Validator, name: vector<u8>) {
