  ctx: &mut TxContext,
 ) {
  let withdrawn_stake = wrapper.request_withdraw_stake_non_entry(staked_sui, ctx);
  transfer::public_transfer(withdrawn_stake.into_coin(ctx), ctx.sender());
 }

public fun request_add_stake_non_entry(
  wrapper: &mut SuiSystemState,
  stake: Coin<SUI>,
  validator_address: address,
  ctx: &mut TxContext,
 ): StakedSui {
  wrapper.load_system_state_mut().request_add_stake(stake.into_balance(), validator_address, ctx)
 }

public fun request_add_stake_mul_coin_non_entry(
  wrapper: &mut SuiSystemState,
  stakes: vector<Coin<SUI>>,
  stake_amount: Option<u64>,
  validator_address: address,
  ctx: &mut TxContext,
 ): StakedSui {
  let balance = stakes.into_balance(stake_amount, ctx);
  wrapper.load_system_state_mut().request_add_stake(balance, validator_address, ctx)
 }

