public(package) fun create(
  balance: Balance<SUI>,
  initial_distribution_amount: u64,
  stake_subsidy_period_length: u64,
  stake_subsidy_decrease_rate: u16,
  ctx: &mut TxContext,
 ): StakeSubsidy {
  assert!(stake_subsidy_decrease_rate <= BASIS_POINT_DENOMINATOR as u16, ESubsidyDecreaseRateTooLarge);
  StakeSubsidy {
  balance,
  distribution_counter: 0,
  current_distribution_amount: initial_distribution_amount,
  stake_subsidy_period_length,
  stake_subsidy_decrease_rate,
  extra_fields: bag::new(ctx),
  }
 }

public(package) fun advance_epoch(self: &mut StakeSubsidy): Balance<SUI> {
  let to_distribute = self.current_distribution_amount.min(self.balance.value());
  self.distribution_counter = self.distribution_counter + 1;
  if (self.distribution_counter % self.stake_subsidy_period_length == 0) {
  let decrease_amount = mul_div!(self.current_distribution_amount, self.stake_subsidy_decrease_rate as u64, BASIS_POINT_DENOMINATOR as u64);
  self.current_distribution_amount = self.current_distribution_amount - decrease_amount;
  };
  self.balance.split(to_distribute)
 }

public(package) fun advance_epoch(
  self: &mut StorageFund,
  storage_charges: Balance<SUI>,
  storage_fund_reinvestment: Balance<SUI>,
  leftover_staking_rewards: Balance<SUI>,
  storage_rebate_amount: u64,
  non_refundable_storage_fee_amount: u64,
 ): Balance<SUI> {
  self.total_object_storage_rebates.join(storage_charges);
  self.total_object_storage_rebates.join(storage_fund_reinvestment);
  self.non_refundable_balance.join(leftover_staking_rewards);
  let storage_rebate = self.total_object_storage_rebates.split(storage_rebate_amount);
  self.non_refundable_balance.join(self.total_object_storage_rebates.split(non_refundable_storage_fee_amount));
  storage_rebate
 }

public(package) fun set_voting_power(validators: &mut vector<Validator>) {
  let num_validators = validators.length();
  let mut i = 0;
  let mut total_stake = 0;
  while (i < num_validators) {
  total_stake = total_stake + validators[i].total_stake();
  i = i + 1;
  };
  let mut i = 0;
  while (i < num_validators) {
  let voting_power = derive_raw_voting_power(validators[i].total_stake(), total_stake);
  validators[i].set_voting_power(voting_power);
  i = i + 1;
  };
 }

