module security::flash_loan {
  public fun execute_arbitrage(pool: &mut Pool, amount: u64, ctx: &mut TxContext) {
  let borrowed = borrow_flash(pool, amount);
  let profit = arbitrage_trade(borrowed);
  repay_flash(pool, borrowed);
  transfer::public_transfer(profit, tx_context::sender(ctx));
  }
 }

