 }

module security::leverage {
  public fun instant_leverage(protocol: &mut Protocol, base: u64, multiplier: u64, ctx: &mut TxContext) {
  let borrowed = base * (multiplier - 1);
  let total = base + borrowed;
  execute_trade(protocol, total, ctx);
  }
 }

module security::atomic_arb {
  public fun atomic_arbitrage(pool_a: &mut Pool, pool_b: &mut Pool, amount: u64) {
  let token_a = pool_a::swap(pool_a, amount);
  let token_b = pool_b::swap(pool_b, token_a);
  assert!(token_b > amount, ERROR_NO_PROFIT);
  }
 }

