module security::multi_hop {
  public fun get_multi_hop_price(oracle: &Oracle, path: vector<String>): u64 {
  let price = PRECISION;
  let i = 0;
  while (i < vector::length(&path) - 1) {
  let rate = get_rate(oracle, *vector::borrow(&path, i), *vector::borrow(&path, i + 1));
  price = (price * rate) / PRECISION;
  i = i + 1;
  };
  price
  }
 }

