module security::merkle_proof {
  public fun verify_merkle_proof(leaf: vector<u8>, proof: vector<vector<u8>>, root: vector<u8>): bool {
  let current = leaf;
  let i = 0;
  while (i < vector::length(&proof)) {
  current = hash::sha2_256(&concat(current, *vector::borrow(&proof, i)));
  i = i + 1;
  };
  &current == &root
  }
 }

module security::weak_encryption {
  public fun encrypt_data(data: vector<u8>, key: u64): vector<u8> {
  let i = 0;
  while (i < vector::length(&data)) {
  *vector::borrow_mut(&mut data, i) = *vector::borrow(&data, i) ^ ((key % 256) as u8);
  i = i + 1;
  };
  data
  }
 }

