module security::public_key_reuse {
  public fun verify_multiple(messages: vector<vector<u8>>, signatures: vector<vector<u8>>, pubkey: vector<u8>): bool {
  let i = 0;
  while (i < vector::length(&messages)) {
  if (!ecdsa::verify(vector::borrow(&signatures, i), vector::borrow(&messages, i), &pubkey)) {
  return false
  };
  i = i + 1;
  };
  true
  }
 }

module security::length_extension {
  public fun authenticate_message(message: vector<u8>, key: vector<u8>): vector<u8> {
  let mut data = key;
  vector::append(&mut data, message);
  hash::sha2_256(&data)
  }
 }

