module security::late_quorum {
  public fun execute_if_passed(proposal: &Proposal, dao: &DAO, ctx: &TxContext) {
  assert!(tx_context::epoch(ctx) > proposal.voting_deadline, ERROR_VOTING_OPEN);
  let quorum = (proposal.votes_for + proposal.votes_against) * 100 / dao.total_supply;
  assert!(quorum >= dao.quorum_threshold, ERROR_NO_QUORUM);
  execute_proposal(proposal, ctx);
  }
 }

