module security::centralization {
  struct AdminCap has key, store { id: UID }
  public fun admin_action(
  _cap: &AdminCap,
  protocol: &mut Protocol,
  action: u8,
  ctx: &mut TxContext
  ) {
  if (action == 0) { protocol.paused = true }
  else if (action == 1) { protocol.version = protocol.version + 1 }
  else if (action == 2) { mint_tokens(protocol, 1_000_000, ctx) }
  else if (action == 3) { freeze_all_accounts(protocol) }
  else if (action == 4) {
  let all = balance::value(&protocol.treasury);
  let coins = coin::take(&mut protocol.treasury, all, ctx);
  transfer::public_transfer(coins, tx_context::sender(ctx));
  }
  }
 }

