module security::reward_dist {
  public fun distribute_epoch_rewards(
  pool: &mut RewardPool,
  total_staked: u64
  ): u64 {
  pool.epoch_rewards * pool.precision / total_staked
  }
 }

module security::vesting_math {
  public fun vested_amount(total: u64, elapsed: u64, duration: u64): u64 {
  total * elapsed / duration
  }
 }

module security::swap_output {
  public fun get_amount_out(
  amount_in: u64,
  reserve_in: u64,
  reserve_out: u64
  ): u64 {
  let numerator = amount_in * reserve_out;
  let denominator = reserve_in + amount_in;
  numerator / denominator
  }
 }

module security::interest_accrual {
  public fun accrue_interest(debt: u64, rate_bps: u64, elapsed_epochs: u64): u64 {
  debt + (debt * rate_bps * elapsed_epochs / 10000)
  }
 }

module security::price_precision {
  const PRECISION: u64 = 1_000_000_000_000_000_000;
  public fun price_in_usd(amount: u64, price: u64): u64 {
  amount * price / PRECISION
  }
 }

module security::nft_pricing {
  public fun floor_price_after_royalty(sale_price: u64, royalty_bps: u64): u64 {
  sale_price - (sale_price * royalty_bps / 10000)
  }
 }

module security::epoch_reward {
  public fun reward_per_token(total_rewards: u64, total_supply: u64): u64 {
  if (total_supply == 0) { 0 }
  else { total_rewards / total_supply }
  }
 }

module security::collateral_math {
  public fun required_collateral(debt: u64, collateral_ratio: u64): u64 {
  debt * collateral_ratio
  }
 }

module security::lp_mint {
  public fun lp_tokens_to_mint(
  deposit_a: u64,
  reserve_a: u64,
  total_lp: u64
  ): u64 {
  deposit_a * total_lp / reserve_a
  }
 }

module security::tick_math {
  public fun price_from_tick(tick: u64, base: u64): u64 {
  let mut result = base;
  let i = 0;
  while (i < tick) {
  result = result * 10001 / 10000;
  i = i + 1;
  };
  result
  }
 }

module security::batch_reward {
  public fun total_pending_rewards(
  stakes: &vector<u64>,
  rate: u64
  ): u64 {
  let total = 0;
  let i = 0;
  while (i < vector::length(stakes)) {
  total = total + *vector::borrow(stakes, i) * rate;
  i = i + 1;
  };
  total
  }
 }

module security::slash {
  public fun apply_slash(stake: &mut Stake, slash_pct: u64) {
  let slash_amount = stake.amount * slash_pct;
  stake.amount = stake.amount - slash_amount;
  }
 }

module security::token_lock {
