  lock.amount = lock.amount + amount;
  }
 }

module security::fee_precision {
  public fun fee_amount(trade_size: u64, fee_numerator: u64, fee_denominator: u64): u64 {
  trade_size * fee_numerator / fee_denominator
  }
 }

module security::power_math {
  public fun pow_u64(base: u64, exp: u64): u64 {
  let result = 1;
  let i = 0;
  while (i < exp) {
  result = result * base;
  i = i + 1;
  };
  result
  }
 }

module security::bond_price {
  public fun bond_payout(
  principal: u64,
  discount_bps: u64,
  vesting_factor: u64
  ): u64 {
  principal * (10000 + discount_bps) * vesting_factor / 10000
  }
 }

module security::supply_cap {
