  oracle: &mut TwapOracle,
  new_price: u64,
  ctx: &TxContext
  ) {
  let elapsed = tx_context::epoch(ctx) - oracle.last_update;
  oracle.cumulative_price = oracle.cumulative_price + new_price * elapsed;
  }
 }

