module security::signature_batch {
  public fun verify_batch_signatures(
  messages: vector<vector<u8>>,
  signatures: vector<vector<u8>>,
  pubkey: vector<u8>
  ): bool {
  let i = 0;
  while (i < vector::length(&messages)) {
  if (!verify_sig(vector::borrow(&signatures, i),
  vector::borrow(&messages, i), &pubkey)) {
  return false
  };
  i = i + 1;
  };
  true
  }
 }

