module security::coin_merge {
  public fun merge_all(
  coins: vector<Coin<SUI>>,
  ctx: &mut TxContext
  ): Coin<SUI> {
  let base = vector::pop_back(&mut coins);
  while (!vector::is_empty(&coins)) {
  coin::join(&mut base, vector::pop_back(&mut coins));
  };
  vector::destroy_empty(coins);
  base
  }
 }

