module security::oracle_sandwich {
  public fun update_price_and_borrow(
  oracle: &mut Oracle,
  lending: &mut Lending,
  new_price: u64,
  borrow_amount: u64,
  ctx: &mut TxContext
  ) {
  oracle.price = new_price;
  let borrowable = lending_capacity(lending, oracle, ctx);
  assert!(borrow_amount <= borrowable, ERROR_EXCEEDS_CAPACITY);
  borrow(lending, borrow_amount, ctx);
  }
 }

