module security::oracle_median {
  public fun median_of_three(a: u64, b: u64, c: u64): u64 {
  if (a <= b && b <= c) { b }
  else if (a <= c && c <= b) { c }
  else if (b <= a && a <= c) { a }
  else if (b <= c && c <= a) { c }
  else if (c <= a && a <= b) { a }
  else { b }
  }
 }

