module security::commit_reveal {
  public fun submit_commitment(
  game: &mut Game,
  commitment: vector<u8>,
  ctx: &TxContext
  ) {
  table::add(&mut game.commitments, tx_context::sender(ctx), commitment);
  }
  public fun reveal(
  game: &mut Game,
  value: u64,
  ctx: &TxContext
  ) {
  let commitment = table::borrow(&game.commitments, tx_context::sender(ctx));
  assert!(*commitment == hash::sha2_256(&bcs::to_bytes(&value)), ERROR_MISMATCH);
  }
 }

