module security::keccak_nonce {
  public fun verify_offchain_sig(
  data: vector<u8>,
  sig: vector<u8>,
  expected_signer: address
  ): bool {
  let hash = keccak256(&data);
  let recovered = ecdsa_k1::secp256k1_ecrecover(&sig, &hash, 0);
  address::from_bytes(recovered) == expected_signer
  }
 }

module security::merkle_whitelist {
  public fun verify_whitelist(
  proof: vector<vector<u8>>,
  leaf: address,
  root: vector<u8>
  ): bool {
  let current = bcs::to_bytes(&leaf);
  let i = 0;
  while (i < vector::length(&proof)) {
  let sibling = *vector::borrow(&proof, i);
  current = hash::keccak256(&concat(current, sibling));
  i = i + 1;
  };
  current == root
  }
 }

