module security::nested_loop {
  public fun cross_product(
  list_a: &vector<u64>,
  list_b: &vector<u64>
  ): vector<u64> {
  let result = vector::empty();
  let i = 0;
  while (i < vector::length(list_a)) {
  let j = 0;
  while (j < vector::length(list_b)) {
  vector::push_back(&mut result, *vector::borrow(list_a, i) * *vector::borrow(list_b, j));
  j = j + 1;
  };
  i = i + 1;
  };
  result
  }
 }

