  let i = 0;
  while (i < vector::length(royalties)) {
  let r = vector::borrow(royalties, i);
  let amount = coin::value(payment) * r.bps / 10000;
  let split = coin::split(payment, amount, ctx);
  transfer::public_transfer(split, r.recipient);
  i = i + 1;
  }
  }
 }

