module security::amm_fee {
  public fun swap_with_fee(
  pool: &mut Pool,
  amount_in: u64,
  ctx: &mut TxContext
  ): u64 {
  let fee = amount_in * pool.fee_bps / 10000;
  let amount_after_fee = amount_in - fee;
  let amount_out = amount_after_fee * pool.reserve_y / pool.reserve_x;
  pool.reserve_x += amount_in;
  pool.reserve_y -= amount_out;
  amount_out
  }
 }

