module security::bridge_sig_order {
  public fun verify_validator_sigs(
  message: &vector<u8>,
  sigs: vector<vector<u8>>,
  validators: &vector<address>
  ): bool {
  let count = 0;
  let i = 0;
  while (i < vector::length(&sigs)) {
  let recovered = recover_signer(vector::borrow(&sigs, i), message);
  if (vector::contains(validators, &recovered)) { count += 1; };
  i = i + 1;
  };
  count >= 2
  }
 }

