public fun commit_upgrade<T>(
  upgrade_service: &mut UpgradeService<T>,
  receipt: UpgradeReceipt,
  ctx: &TxContext
  ) {
  upgrade_service.admin.assert_sender_is_active_role(ctx);
  upgrade_service.assert_upgrade_cap_exists();

  let new_package_id = receipt.package();
  upgrade_service.borrow_upgrade_cap_mut().commit(receipt);

  event::emit(CommitUpgrade<T> { 
  package_id: new_package_id
  });
  }

public fun begin_role_transfer<T>(
  role: &mut TwoStepRole<T>,
  new_address: address,
  ctx: &TxContext
  ) {
  role.assert_sender_is_active_role(ctx);

  role.pending_address = option::some(new_address);

  event::emit(RoleTransferStarted<T> {
  old_address: role.active_address,
  new_address,
  });
  }

public fun accept_role<T>(
  role: &mut TwoStepRole<T>,
  ctx: &TxContext
  ) {
  assert!(role.pending_address.is_some(), EPendingAddressNotSet);
  assert!(role.pending_address.contains(&ctx.sender()), ESenderNotPendingAddress);

  let old_address = role.active_address;
  role.active_address = role.pending_address.extract();

  event::emit(RoleTransferred<T> {
  old_address,
  new_address: role.active_address
  });
  }

public(package) fun update_blocklister<T>(roles: &mut Roles<T>, new_blocklister: address, ctx: &TxContext) {
  roles.owner_role().assert_sender_is_active_role(ctx);

  let old_blocklister = roles.update_address(BlocklisterKey {}, new_blocklister);

  event::emit(BlocklisterChanged<T> {
  old_blocklister,
  new_blocklister
  });
  }

